#ifndef MARKETCANOPY_TEST_SUPPORT_H
#define MARKETCANOPY_TEST_SUPPORT_H

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <functional>
#include <sstream>
#include <string>
#include <vector>

#include "fixture_list.h" // generated by CMakeLists.txt: MC_FIXTURES_DIR, MC_FIXTURE_FILES
#include "json.h"

namespace NSTest
{
	using NSMarketCanopy::Json;

	inline int& Failures()
	{
		static int failures = 0;
		return failures;
	}

	inline void Fail(const std::string& where, const std::string& what)
	{
		++Failures();
		std::printf("FAIL %s: %s\n", where.c_str(), what.c_str());
	}

#define CHECK(condition, where) \
	do { if (!(condition)) NSTest::Fail(where, "CHECK(" #condition ") at line " + std::to_string(__LINE__)); } while (0)
#define CHECK_EQ(actual, expected, where) \
	do { if (!((actual) == (expected))) NSTest::Fail(where, std::string(#actual " is \"") + NSTest::Text(actual) + "\", expected \"" + NSTest::Text(expected) + "\" at line " + std::to_string(__LINE__)); } while (0)

	inline std::string Text(const std::string& value) { return value; }
	inline std::string Text(const char* value) { return value ? value : "(null)"; }
	inline std::string Text(bool value) { return value ? "true" : "false"; }
	inline std::string Text(int value) { return std::to_string(value); }
	inline std::string Text(long long value) { return std::to_string(value); }
	inline std::string Text(size_t value) { return std::to_string(value); }

	inline std::string ReadFile(const std::string& path)
	{
		std::ifstream in(path.c_str(), std::ios::binary);
		if (!in)
		{
			Fail("ReadFile", "cannot open " + path);
			return std::string();
		}
		std::ostringstream text;
		text << in.rdbuf();
		return text.str();
	}

	// contracts/fixtures/<relative>, parsed
	inline Json Fixture(const std::string& relative)
	{
		Json value;
		if (!Json::Parse(ReadFile(std::string(MC_FIXTURES_DIR) + "/" + relative), value))
			Fail("Fixture", relative + " is not JSON");
		return value;
	}

	// Every fixture file in contracts/fixtures/<folder>, sorted, as listed by
	// CMake when it configured the build (so no directory API is needed).
	inline std::vector<std::string> FixtureFiles(const std::string& folder)
	{
		std::vector<std::string> files;
		std::stringstream all(MC_FIXTURE_FILES);
		std::string item;
		while (std::getline(all, item, ';'))
			if (item.compare(0, folder.size() + 1, folder + "/") == 0)
				files.push_back(item);
		return files;
	}

	// JSON equality with object members compared by key, not by order.
	inline bool Same(const Json& a, const Json& b)
	{
		if (a.GetType() != b.GetType())
			return false;
		switch (a.GetType())
		{
		case Json::Null: return true;
		case Json::Bool: return a.AsBool() == b.AsBool();
		case Json::Number: return a.AsNumber() == b.AsNumber();
		case Json::String: return a.AsString() == b.AsString();
		case Json::Array:
			if (a.Size() != b.Size())
				return false;
			for (size_t i = 0; i < a.Size(); ++i)
				if (!Same(a.At(i), b.At(i)))
					return false;
			return true;
		case Json::Object:
			if (a.Size() != b.Size())
				return false;
			for (size_t i = 0; i < a.Members().size(); ++i)
			{
				const std::string& key = a.Members()[i].first;
				if (!b.Has(key) || !Same(a.Members()[i].second, b.Get(key)))
					return false;
			}
			return true;
		}
		return false;
	}

	inline void CheckSame(const Json& actual, const Json& expected, const std::string& where)
	{
		if (!Same(actual, expected))
			Fail(where, "got " + actual.Dump() + ", expected " + expected.Dump());
	}

	inline std::string Replace(std::string text, const std::string& from, const std::string& to)
	{
		for (size_t at = text.find(from); at != std::string::npos; at = text.find(from, at + to.size()))
			text.replace(at, from.size(), to);
		return text;
	}

	inline int Finish(const char* suite)
	{
		if (Failures())
		{
			std::printf("%s: %d failed\n", suite, Failures());
			return 1;
		}
		std::printf("%s: all passed\n", suite);
		return 0;
	}
}

#endif // MARKETCANOPY_TEST_SUPPORT_H
